/* @lc app=leetcode id=3410 lang=kotlin */ class Solution { fun nu() = longArrayOf(0L, -100_000_000_000_000_000L, -100_000_000_000_000_000L, -100_000_000_000_000_000L) fun lf(v: Long) = longArrayOf(v, v, v, v) fun mg(a: LongArray, b: LongArray): LongArray = longArrayOf(a[0] + b[0], maxOf(a[1], a[0] + b[1]), maxOf(b[2], b[0] + a[2]), maxOf(a[3], b[3], a[2] + b[1])) fun st(t: Array<LongArray>, sz: Int, p: Int, v: Long) = t.set(sz + p, lf(v)).let { generateSequence((sz + p) / 2) { it / 2 }.takeWhile { it >= 1 }.forEach { i -> t[i] = mg(t[2 * i], t[2 * i + 1]) } } fun maxSubarraySum(nums: IntArray): Long = generateSequence(1) { it * 2 }.first { it >= nums.size }.let { sz -> Array(2 * sz) { nu() }.also { t -> nums.indices.forEach { t[sz + it] = lf(nums[it].toLong()) } }.also { t -> (sz - 1 downTo 1).forEach { t[it] = mg(t[2 * it], t[2 * it + 1]) } }.let { t -> nums.max().let { m1 -> (nums.filter { it != m1 }.maxOrNull() ?: m1).let { m2 -> nums.indices.groupBy { nums[it] }.entries.fold(t[1][3]) { best, (x, ps) -> if (ps.size == nums.size) best else ps.forEach { st(t, sz, it, 0L) }.let { t[1][3].let { b -> if (b > 0) b else (if (x != m1) m1 else m2).toLong() }.let { c -> ps.forEach { st(t, sz, it, nums[it].toLong()) }.let { maxOf(best, c) } } } } } } } } }